def share(slug,title,category,image):
 d=OUT/'share';d.mkdir(exist_ok=True)
 im=Image.new('RGB',(1200,630),'#1d382d');pic=Image.open(OUT/'media'/f'{image}.webp').convert('RGB');pic=ImageOps.fit(pic,(510,630));im.paste(pic,(690,0));draw=ImageDraw.Draw(im);draw.text((55,47),'BeeGoods.',font=ImageFont.truetype(font,43),fill='#edb851');draw.text((55,139),category.upper()[:40],font=ImageFont.truetype(bold,15),fill='#e9d8a6');y=193
 for line in textwrap.wrap(title,23):draw.text((55,y),line,font=ImageFont.truetype(font,46),fill='#fff8e7');y+=57
 draw.text((55,570),'BEEGOODS.CO  /  THE NEXT LITTLE BUZZ',font=ImageFont.truetype(bold,13),fill='#d7dfca');im.save(d/f'{slug}.jpg',quality=90)
 return f'/share/{slug}.jpg'
