 html=f'<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} | BeeGoods</title><meta name="description" content="{E(description)}"><link rel="canonical" href="{canonical}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(description)}"><meta property="og:type" content="{"article" if article else "website"}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{URL+og}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="{E(title)} — BeeGoods editorial card"><meta property="og:locale" content="en_CA"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="{URL+og}"><meta name="twitter:title" content="{E(title)}"><meta name="twitter:description" content="{E(description)}"><link rel="icon" href="/logo.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">{json.dumps(ld)}</script></head><body>{HEADER}<main id="main">{body}</main>{FOOTER}<script src="/site.js" defer></script></body></html>'
