def video_break(key,kicker,title,text):
 source,credit=SOURCES[key]
 return f'<section class="video-break" data-topic="{key}" aria-label="{E(title)}"><video muted loop playsinline preload="none" poster="/media/{key}.webp"><source src="/media/{key}.mp4" type="video/mp4"></video><div class="break-copy"><div class="kicker">{E(kicker)}</div><h2>{E(title)}</h2><p>{E(text)}</p></div><button class="motion" type="button" aria-pressed="false" aria-label="Pause {E(kicker)} video">Pause video</button><small>Illustrative footage · <a href="{source}" target="_blank" rel="noopener">{credit} ↗</a> · Not BeeGoods products or apiary.</small></section>'
def card(a):
 slug,title,cat,img,desc,_=a
 return f'<a class="card" href="/journal/{slug}/"><img src="/share/journal-{slug}.jpg" width="1200" height="630" loading="lazy" alt="{E(title)} — illustrated editorial guide"><div class="card-body"><div class="kicker">{E(cat)}</div><time datetime="{DATE}">October 17, 2026</time><h3>{E(title)}</h3><p>{E(desc)}</p><span class="read">Read the story ↗</span></div></a>'
